542	  /**
543	   * The YARN Router will forward to the respective YARN RM in which the AM is
544	   * running.
545	   *
546	   * Possible failure:
547	   *
548	   * Client: identical behavior as {@code ClientRMService}.
549	   *
550	   * Router: the Client will timeout and resubmit the request.
551	   *
552	   * ResourceManager: the Router will timeout and the call will fail.
553	   *
554	   * State Store: the Router will timeout and it will retry depending on the
555	   * FederationFacade settings - if the failure happened before the select
556	   * operation.
557	   */
558	  @Override
559	  public GetApplicationReportResponse getApplicationReport(
560	      GetApplicationReportRequest request) throws YarnException, IOException {
561	
562	    long startTime = clock.getTime();
563	
