67	/**
68	 * Extends the {@code BaseRouterClientRMTest} and overrides methods in order to
69	 * use the {@code RouterClientRMService} pipeline test cases for testing the
70	 * {@code FederationInterceptor} class. The tests for
71	 * {@code RouterClientRMService} has been written cleverly so that it can be
72	 * reused to validate different request intercepter chains.
73	 */
74	public class TestFederationClientInterceptor extends BaseRouterClientRMTest {
75	  private static final Logger LOG =
76	      LoggerFactory.getLogger(TestFederationClientInterceptor.class);
77	
78	  private TestableFederationClientInterceptor interceptor;
79	  private MemoryFederationStateStore stateStore;
80	  private FederationStateStoreTestUtil stateStoreUtil;
81	  private List<SubClusterId> subClusters;
82	
83	  private String user = "test-user";
84	
85	  private final static int NUM_SUBCLUSTER = 4;
86	
87	  @Override
88	  public void setUp() {
89	    super.setUpConfig();
90	    interceptor = new TestableFederationClientInterceptor();
91	
92	    stateStore = new MemoryFederationStateStore();
93	    stateStore.init(this.getConf());
94	    FederationStateStoreFacade.getInstance().reinitialize(stateStore,
95	        getConf());
96	    stateStoreUtil = new FederationStateStoreTestUtil(stateStore);
97	
98	    interceptor.setConf(this.getConf());
99	    interceptor.init(user);
100	
101	    subClusters = new ArrayList<SubClusterId>();
102	
103	    try {
104	      for (int i = 0; i < NUM_SUBCLUSTER; i++) {
105	        SubClusterId sc = SubClusterId.newInstance(Integer.toString(i));
106	        stateStoreUtil.registerSubCluster(sc);
107	        subClusters.add(sc);
108	      }
109	    } catch (YarnException e) {
110	      LOG.error(e.getMessage());
111	      Assert.fail();
112	    }
113	
114	  }
115	
116	  @Override
117	  public void tearDown() {
118	    interceptor.shutdown();
119	    super.tearDown();
120	  }
121	
122	  @Override
123	  protected YarnConfiguration createConfiguration() {
124	    YarnConfiguration conf = new YarnConfiguration();
125	    conf.setBoolean(YarnConfiguration.FEDERATION_ENABLED, true);
126	    String mockPassThroughInterceptorClass =
127	        PassThroughClientRequestInterceptor.class.getName();
128	
129	    // Create a request intercepter pipeline for testing. The last one in the
130	    // chain is the federation intercepter that calls the mock resource manager.
131	    // The others in the chain will simply forward it to the next one in the
132	    // chain
133	    conf.set(YarnConfiguration.ROUTER_CLIENTRM_INTERCEPTOR_CLASS_PIPELINE,
134	        mockPassThroughInterceptorClass + "," + mockPassThroughInterceptorClass
135	            + "," + TestableFederationClientInterceptor.class.getName());
136	
137	    conf.set(YarnConfiguration.FEDERATION_POLICY_MANAGER,
138	        UniformBroadcastPolicyManager.class.getName());
139	
140	    // Disable StateStoreFacade cache
141	    conf.setInt(YarnConfiguration.FEDERATION_CACHE_TIME_TO_LIVE_SECS, 0);
142	
143	    return conf;
144	  }
